@namespace sv_b78a47ad765b456b85cc30162431db39.Components.Pages.Settings

<nav class="settings-sidebar">
    <h5 class="px-3 py-2 text-muted">Settings</h5>
    <ul class="nav flex-column">
        @foreach (var section in Sections)
        {
            <li class="nav-item">
                <a class="nav-link @(section == ActiveSection ? "active" : "")"
                   href=""
                   @onclick="() => OnSectionChanged.InvokeAsync(section)"
                   @onclick:preventDefault>
                    <span class="me-2">@GetIcon(section)</span>@section
                </a>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_b78a47ad765b456b85cc30162431db39.Components.Pages.Settings
@using sv_b78a47ad765b456b85cc30162431db39.Services

<div class="settings-section">
    <h3>Profile</h3>
    <hr />

    @if (_profile is not null)
    {
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label class="form-label">Display Name</label>
                    <input type="text" class="form-control" @bind="_displayName" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="_email" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Bio</label>
                    <textarea class="form-control" rows="4" @bind="_bio"></textarea>
                </div>
            </div>
            <div class="col-md-4">
                <div class="text-center">
                    <div class="avatar-preview mb-2">
                        <img src="@_avatarUrl" alt="Avatar" class="rounded-circle img-fluid" style="width: 120px; height: 120px; object-fit: cover;" />
                    </div>
                    <small class="text-muted d-block text-truncate">@_avatarUrl</small>
                </div>
            </div>
        </div>

        <div class="mt-3">
            <button class="btn btn-primary me-2" @onclick="SaveChanges">Save Changes</button>
            <button class="btn btn-outline-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>

        @if (_showSuccess)
        {
            <div class="alert alert-success mt-3 fade show" role="alert">
                Profile saved successfully!
            </div>
        }
    }
    else
    {
        <p class="text-muted">Loading profile...</p>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && _profile is null)
        {
            _profile = Profile;
            ResetFields();
        }
    }

    private void ResetFields()
    {
        if (_profile is null) return;
        _displayName = _profile.DisplayName;
        _email = _profile.Email;
        _avatarUrl = _profile.AvatarUrl;
        _bio = _profile.Bio;
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await OnSave.InvokeAsync(updated);
        _profile = updated;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void DiscardChanges()
    {
        _profile = Profile;
        ResetFields();
    }
}

