@namespace sv_b78a47ad765b456b85cc30162431db39.Components.Pages.Settings
@using sv_b78a47ad765b456b85cc30162431db39.Services

<div class="mb-3">
    <h5>Active Sessions</h5>
    <div class="table-responsive">
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@FormatLastActive(session.LastActive)</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-sm btn-outline-danger" @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="badge bg-success">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
</div>

@if (_sessionToRevoke is not null)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Confirm Session Revocation</h5>
                    <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "sess-1";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? _sessionToRevoke;

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevoke.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

@namespace sv_b78a47ad765b456b85cc30162431db39.Components.Pages.Settings
@using sv_b78a47ad765b456b85cc30162431db39.Services

<div class="settings-section">
    <h3>Security</h3>
    <hr />

    @if (_settings is not null)
    {
        <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

        <div class="card mb-3">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <strong>Two-Factor Authentication</strong>
                    <br />
                    <small class="text-muted">
                        @if (_twoFactorEnabled)
                        {
                            <span class="text-success">● Enabled</span>
                        }
                        else
                        {
                            <span class="text-danger">● Disabled</span>
                        }
                    </small>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" checked="@_twoFactorEnabled" @onchange="e => _twoFactorEnabled = (bool)e.Value!" />
                </div>
            </div>
        </div>

        @if (_settings.LastPasswordChange.HasValue)
        {
            <p class="text-muted small">Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }

        <ActiveSessionsTable Sessions="@_sessions" CurrentSessionId="sess-1" OnRevoke="HandleRevokeSession" />
    }
    else
    {
        <p class="text-muted">Loading security settings...</p>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private SecuritySettings? _settings;
    private List<ActiveSession> _sessions = new();
    private bool _twoFactorEnabled;

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            _settings = Settings;
            _sessions = Settings.Sessions.ToList();
            _twoFactorEnabled = Settings.TwoFactorEnabled;
        }
    }

    private async Task HandleChangePassword((string Current, string New) args)
    {
        await OnChangePassword.InvokeAsync(args);
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await OnRevokeSession.InvokeAsync(sessionId);
        _sessions = _sessions.Where(s => s.Id != sessionId).ToList();
    }
}

