@namespace sv_b78a47ad765b456b85cc30162431db39.Components.Pages.Settings
@using sv_b78a47ad765b456b85cc30162431db39.Services

<div class="settings-section">
    <h3>Appearance</h3>
    <hr />

    @if (_settings is not null)
    {
        <div class="row">
            <div class="col-md-7">
                <div class="mb-4">
                    <h5>Theme</h5>
                    <div class="btn-group" role="group">
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <input type="radio" class="btn-check" name="theme" id="@($"theme-{theme}")"
                                   checked="@(_theme == theme)" @onchange="() => _theme = theme" />
                            <label class="btn btn-outline-primary" for="@($"theme-{theme}")">@theme</label>
                        }
                    </div>
                </div>

                <div class="mb-4">
                    <h5>Font Size</h5>
                    <div class="btn-group" role="group">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <input type="radio" class="btn-check" name="fontSize" id="@($"size-{size}")"
                                   checked="@(_fontSize == size)" @onchange="() => _fontSize = size" />
                            <label class="btn btn-outline-secondary" for="@($"size-{size}")">@size</label>
                        }
                    </div>
                </div>

                <div class="mb-4">
                    <h5>Language</h5>
                    <select class="form-select" style="max-width: 250px;" @bind="_language">
                        <option value="English">English</option>
                        <option value="Spanish">Spanish</option>
                        <option value="French">French</option>
                        <option value="German">German</option>
                        <option value="Japanese">Japanese</option>
                        <option value="Chinese">Chinese</option>
                    </select>
                </div>

                <div class="mb-4">
                    <h5>Compact Mode</h5>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode"
                               checked="@_compactMode" @onchange="e => _compactMode = (bool)e.Value!" />
                        <label class="form-check-label" for="compactMode">Enable compact mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="Save">Save</button>

                @if (_showSuccess)
                {
                    <div class="alert alert-success mt-3 fade show" role="alert">
                        Appearance settings saved!
                    </div>
                }
            </div>

            <div class="col-md-5">
                <h5>Preview</h5>
                <div class="border rounded p-3 @GetPreviewClasses()" style="@GetPreviewStyles()">
                    <div class="mb-2"><strong>Sample Heading</strong></div>
                    <p class="mb-2">This is how your content will look with the selected settings.</p>
                    <div class="d-flex gap-2">
                        <button class="btn btn-sm btn-primary">Action</button>
                        <button class="btn btn-sm btn-outline-secondary">Cancel</button>
                    </div>
                    <hr />
                    <small class="text-muted">Theme: @_theme | Font: @_fontSize | Lang: @_language</small>
                </div>
            </div>
        </div>
    }
    else
    {
        <p class="text-muted">Loading appearance settings...</p>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private AppearanceSettings? _settings;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _showSuccess;

    protected override void OnParametersSet()
    {
        if (Settings is not null && _settings is null)
        {
            _settings = Settings;
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private async Task Save()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _settings = updated;
        _showSuccess = true;
        _ = HideSuccessAfterDelay();
    }

    private async Task HideSuccessAfterDelay()
    {
        await Task.Delay(3000);
        _showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private string GetPreviewClasses()
    {
        var classes = "";
        if (_theme == "Dark") classes += " bg-dark text-light";
        else classes += " bg-white";
        if (_compactMode) classes += " py-1 px-2";
        return classes;
    }

    private string GetPreviewStyles()
    {
        var fontSize = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size: {fontSize}; min-height: 180px;";
    }
}

