@page "/settings"
@namespace sv_b78a47ad765b456b85cc30162431db39.Components.Pages.Settings
@using sv_b78a47ad765b456b85cc30162431db39.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-layout">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection Profile="@_profile" OnSave="SaveProfile" />
                break;
            case "Notifications":
                <NotificationsSection Prefs="@_notifications" OnSave="SaveNotifications" />
                break;
            case "Security":
                <SecuritySection Settings="@_security" OnChangePassword="ChangePassword" OnRevokeSession="RevokeSession" />
                break;
            case "Appearance":
                <AppearanceSection Settings="@_appearance" OnSave="SaveAppearance" />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";
    private UserProfile? _profile;
    private NotificationPrefs? _notifications;
    private SecuritySettings? _security;
    private AppearanceSettings? _appearance;

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        _notifications = await SettingsService.GetNotificationPrefsAsync();
        _security = await SettingsService.GetSecuritySettingsAsync();
        _appearance = await SettingsService.GetAppearanceAsync();
    }

    private void SetActiveSection(string section) => _activeSection = section;

    private async Task SaveProfile(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotifications(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notifications = prefs;
    }

    private async Task ChangePassword((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearance(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
    }
}

.settings-layout {
    display: flex;
    min-height: calc(100vh - 100px);
    gap: 0;
}

.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background-color: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding-top: 1rem;
}

.settings-sidebar .nav-link {
    color: #495057;
    padding: 0.6rem 1.2rem;
    border-radius: 0;
    border-left: 3px solid transparent;
    transition: all 0.15s;
}

.settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
    color: #212529;
}

.settings-sidebar .nav-link.active {
    background-color: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 500;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 900px;
}

.settings-section h3 {
    margin-bottom: 0.5rem;
}

